mapper.select:
select ma.apply_id as applyId, ma.account_id as accountId, a.nick_name as accountNickName, a.mobile as accountMobile, ma.merchant_id as merchantId, m.merchant_name as linkedMerchantName, ma.apply_type as applyType, ma.merchant_name as merchantName, ma.category_id as categoryId, mc.category_name as categoryName, ma.logo as logo, ma.contact_name as contactName, ma.contact_phone as contactPhone, ma.license_files as licenseFiles, ma.open_status as openStatus, ma.status as status, ma.reject_reason as rejectReason, ma.audit_time as auditTime, ma.del_flag as delFlag, ma.create_time as createTime, ma.update_time as updateTime, ma.remark as remark from merchant_apply ma left join account a on ma.account_id = a.account_id and a.del_flag = 0 left join merchant m on ma.merchant_id = m.merchant_id and m.del_flag = 0 left join merchant_category mc on ma.category_id = mc.category_id and mc.del_flag = 0 where ma.del_flag = 0
and ma.account_id = #{accountId}
and a.nick_name like concat('%', #{accountNickName}, '%')
and a.mobile like concat('%', #{accountMobile}, '%')
and ma.merchant_id = #{merchantId}
and ma.apply_type = #{applyType}
and ma.merchant_name like concat('%', #{merchantName}, '%')
and ma.category_id = #{categoryId}
and mc.category_name like concat('%', #{categoryName}, '%')
and ma.contact_name like concat('%', #{contactName}, '%')
and ma.contact_phone like concat('%', #{contactPhone}, '%')
and ma.open_status = #{openStatus}
and ma.status = #{status}
order by ma.apply_id desc

