    and ma.contact_name like concat('%', #{contactName}, '%')


    and ma.contact_phone like concat('%', #{contactPhone}, '%')


    and ma.open_status = #{openStatus}


    and ma.status = #{status}

select ma.apply_id, ma.account_id, ma.merchant_id, ma.apply_type, ma.merchant_name, ma.category_id, ma.logo, ma.contact_name, ma.contact_phone, ma.license_files, ma.open_status, ma.status, ma.reject_reason, ma.audit_time, ma.del_flag, ma.create_time, ma.update_time, ma.remark from merchant_apply ma where ma.del_flag = 0
and ma.account_id = #{accountId}
and ma.merchant_id = #{merchantId}
and ma.apply_type = #{applyType}
and ma.merchant_name like concat('%', #{merchantName}, '%')
and ma.category_id = #{categoryId}
and ma.contact_name like concat('%', #{contactName}, '%')
and ma.contact_phone like concat('%', #{contactPhone}, '%')
